rv = CallCreateInstance(MOZ_TXTTOHTMLCONV_CONTRACTID, &(msd->options->conv));
if (NS_FAILED(rv)) {
  PR_Free(msd->options);
  delete msd;
  return nullptr;
}

  write_pure_bodies = false;
  metadata_only = false;
}

